// SignaturePad v3.1.0 - Compatible con tablets y móviles (optimizado para Chrome / Samsung)
class SignaturePad {
  constructor(canvas, options = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { willReadFrequently: true });
    this.options = {
      penColor: 'rgb(66, 133, 244)',
      backgroundColor: 'rgb(255, 255, 255)',
      minWidth: 0.5,
      maxWidth: 2.5,
      throttle: 16,
      minDistance: 3,
      ...options
    };
    this.points = [];
    this.isDrawing = false;
    this.activePointerId = null;
    this.lastTime = 0;
    this.lastX = 0;
    this.lastY = 0;

    // Handlers con bind explícito para permitir unbind limpio en destroy()
    this._onPointerDown = e => this._handlePointerStart(e);
    this._onPointerMove = e => this._handlePointerMove(e);
    this._onPointerUp = e => this._handlePointerEnd(e);
    this._onPointerCancel = e => this._handlePointerEnd(e);

    this._bindEvents();
    this.clear();
  }

  _bindEvents() {
    this.canvas.addEventListener('pointerdown', this._onPointerDown, { passive: false });
    this.canvas.addEventListener('pointermove', this._onPointerMove, { passive: false });
    this.canvas.addEventListener('pointerup', this._onPointerUp, { passive: false });
    this.canvas.addEventListener('pointercancel', this._onPointerCancel, { passive: false });
  }

  destroy() {
    this.canvas.removeEventListener('pointerdown', this._onPointerDown);
    this.canvas.removeEventListener('pointermove', this._onPointerMove);
    this.canvas.removeEventListener('pointerup', this._onPointerUp);
    this.canvas.removeEventListener('pointercancel', this._onPointerCancel);
    this.isDrawing = false;
    this.activePointerId = null;
    this.points = [];
  }

  _handlePointerStart(e) {
    // Si ya hay un puntero activo (multi-touch / rechazo de palma), ignorar punteros adicionales
    if (this.activePointerId !== null && this.activePointerId !== e.pointerId) return;

    if (e.cancelable) e.preventDefault();
    this.activePointerId = e.pointerId;
    this.isDrawing = true;

    // Capturar el puntero para que los trazos no se corten al salir ligeramente del canvas
    if (typeof this.canvas.setPointerCapture === 'function') {
      try {
        this.canvas.setPointerCapture(e.pointerId);
      } catch (_) {
        // Ignorar si el navegador no permite captura en este contexto
      }
    }

    const pos = this._getPos(e);
    this.lastX = pos.x;
    this.lastY = pos.y;
    this.lastTime = Date.now();

    // IMPORTANTE: Registrar el punto inicial para que toques, puntos finales o firmas cortas se cuenten válidas
    this.points.push({ x: pos.x, y: pos.y, t: this.lastTime });
    this._drawPoint(pos.x, pos.y);
  }

  _handlePointerMove(e) {
    if (!this.isDrawing) return;
    if (this.activePointerId !== null && e.pointerId !== this.activePointerId) return;
    if (e.cancelable) e.preventDefault();

    const now = Date.now();
    if (now - this.lastTime < this.options.throttle) return;

    const pos = this._getPos(e);
    const dist = Math.hypot(pos.x - this.lastX, pos.y - this.lastY);

    if (dist < this.options.minDistance) return;

    this.points.push({ x: pos.x, y: pos.y, t: now });
    this._drawLine(this.lastX, this.lastY, pos.x, pos.y);
    this.lastX = pos.x;
    this.lastY = pos.y;
    this.lastTime = now;
  }

  _handlePointerEnd(e) {
    if (e && this.activePointerId !== null && e.pointerId !== this.activePointerId) return;
    if (e && e.cancelable) e.preventDefault();

    if (e && typeof this.canvas.releasePointerCapture === 'function' && this.activePointerId !== null) {
      try {
        this.canvas.releasePointerCapture(this.activePointerId);
      } catch (_) {}
    }

    this.isDrawing = false;
    this.activePointerId = null;
  }

  _getPos(e) {
    const rect = this.canvas.getBoundingClientRect();
    const rw = rect.width > 0 ? rect.width : (this.canvas.width || 1);
    const rh = rect.height > 0 ? rect.height : (this.canvas.height || 1);
    const clientX = e.clientX !== undefined ? e.clientX : (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
    const clientY = e.clientY !== undefined ? e.clientY : (e.touches && e.touches[0] ? e.touches[0].clientY : 0);

    return {
      x: (clientX - rect.left) * (this.canvas.width / rw),
      y: (clientY - rect.top) * (this.canvas.height / rh)
    };
  }

  _drawPoint(x, y) {
    this.ctx.fillStyle = this.options.penColor;
    this.ctx.beginPath();
    this.ctx.arc(x, y, this.options.minWidth, 0, Math.PI * 2);
    this.ctx.fill();
  }

  _drawLine(x1, y1, x2, y2) {
    this.ctx.strokeStyle = this.options.penColor;
    this.ctx.lineWidth = this.options.maxWidth;
    this.ctx.lineCap = 'round';
    this.ctx.lineJoin = 'round';
    this.ctx.beginPath();
    this.ctx.moveTo(x1, y1);
    this.ctx.lineTo(x2, y2);
    this.ctx.stroke();
  }

  clear() {
    this.ctx.fillStyle = this.options.backgroundColor;
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
    this.points = [];
    this.isDrawing = false;
    this.activePointerId = null;
  }

  isEmpty() {
    return !this.points || this.points.length === 0;
  }

  toDataURL(type = 'image/png') {
    return this.canvas.toDataURL(type);
  }

  toData() {
    return this.points;
  }

  fromData(pointGroups) {
    this.clear();
    if (!Array.isArray(pointGroups)) return;
    pointGroups.forEach(group => {
      if (!Array.isArray(group)) return;
      group.forEach((point, index) => {
        if (index === 0) {
          this._drawPoint(point.x, point.y);
        } else {
          const prev = group[index - 1];
          this._drawLine(prev.x, prev.y, point.x, point.y);
        }
      });
    });
  }
}
